head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL21101";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_sessionFill();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil21101.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comNm"] ?? ""); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_applDd", fn: function () { return String(String((dma_pageContext.get("today") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["isurCd"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil21101' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fn_Register, tx_fn_Submit) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_linkDisclsApplList_oncellclick
 * @description grd_linkDisclsApplList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_linkDisclsApplList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_linkDisclsApplList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_linkDisclsApplList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.loadForm(r["lnkDisclsApplSeq"], r["subcomNm"], r["subcomIsurCd"], r["asstTotamtOvr10pctYn"], r["lnkDisclsApplApplDd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_linkDisclsApplList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_findCompany_onclick
 * @description btn_findCompany 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_findCompany_onclick = async function(e){
    try {
        await scwin.findCompany()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil21101.btn_findCompany_onclick' }); }
};

/**
 * @method
 * @name btn_goStatList_onclick
 * @description btn_goStatList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goStatList_onclick = function(e){
    try {
        scwin.goStatList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil21101.btn_goStatList_onclick' }); }
};

/**
 * @method
 * @name btn_Register_onclick
 * @description btn_Register 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Register_onclick = async function(e){
    try {
        await scwin.register('N')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil21101.btn_Register_onclick' }); }
};

/**
 * @method
 * @name btn_Register_2_onclick
 * @description btn_Register_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Register_2_onclick = async function(e){
    try {
        await scwin.register('Y')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil21101.btn_Register_2_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/company/linkDisclsAppl.do",
        ref: "dma_RegisterReq",
        target: "dlt_linkDisclsApplList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Submit
 * @description Submit 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Submit = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Submit",
        method: "post",
        action: action ?? "/company/linkDisclsAppl.do",
        ref: "dma_SubmitReq",
        target: "dlt_linkDisclsApplList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name loadForm
 * @description load Form 처리
 * @param {*} lnkDisclsApplSeq lnkDisclsApplSeq
 * @param {String} subcomNm subcomNm
 * @param {String} subcomIsurCd subcomIsurCd
 * @param {String} rd_asstTotamtOvr10pctYn rd_asstTotamtOvr10pctYn
 * @param {String} lnkDisclsApplApplDd lnkDisclsApplApplDd
 * @returns {void}
 * @hidden N
 */
scwin.loadForm = function (lnkDisclsApplSeq, subcomNm, subcomIsurCd, rd_asstTotamtOvr10pctYn, lnkDisclsApplApplDd) {
    $c.util.getComponent("dma_RegisterReq").set("lnkDisclsApplSeq", lnkDisclsApplSeq);
    $c.util.getComponent('ipt_subcomNm').setValue(subcomNm);
    $c.util.getComponent("dma_RegisterReq").set("subcomIsurCd", subcomIsurCd);
    const obj = $c.util.getComponent('rd_asstTotamtOvr10pctYn');
    for (let i = 0; i < obj.length; i++) {
        if (obj[i].value === rd_asstTotamtOvr10pctYn) {
            obj[i].checked = true;
        }
    }
    const regexp = /-/g;
    const undashApplDd = lnkDisclsApplApplDd.replace(regexp, "");
    $c.util.getComponent('cal_lnkDisclsApplApplDd').setValue(undashApplDd);
};

/**
 * @method
 * @name chk
 * @description chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk = async function () {
    if ($c.util.getComponent('ipt_applDd').getValue()>= $c.util.getComponent('cal_lnkDisclsApplApplDd').getValue()) {
        await $c.win.alert('연계공시 적용신청일은  신청일보다 이후 일자 이어야 합니다.');
        $c.util.getComponent("cal_lnkDisclsApplApplDd").focus();
        return false;
    }
    if (($c.util.getComponent('cal_lnkDisclsApplApplDd').getValue() == null ? '' : String($c.util.getComponent('cal_lnkDisclsApplApplDd').getValue())) === '' || $c.util.getComponent('cal_lnkDisclsApplApplDd').getValue().indexOf(" ") === "") {
        await $c.win.alert("연계공시 적용신청일을 입력해 주세요");
        $c.util.getComponent("cal_lnkDisclsApplApplDd").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_subcomNm').getValue() == null ? '' : String($c.util.getComponent('ipt_subcomNm').getValue())) === '' || $c.util.getComponent('ipt_subcomNm').getValue().indexOf(" ") === "") {
        await $c.win.alert("상장자회사를 입력해 주세요");
        $c.util.getComponent("ipt_subcomNm").focus();
        return false;
    }
    let aChecked = false;
    const obj = $c.util.getComponent('rd_asstTotamtOvr10pctYn');
    for (let i = 0; i < obj.length; i++) {
        if (obj[i].checked === true) {
            aChecked = true;
            break;
        }
    }
    if (!aChecked) {
        await $c.win.alert("지주회사 자산총액 대비 비중을 선택해 주세요");
        $c.util.getComponent("rd_asstTotamtOvr10pctYn").focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function (_submitYn) {

    const frm = (document.linkDisclsAppForm || { elements: [] });

    if ((String(($c.session.getUserInfo("isurCd")) == null ? '' : ($c.session.getUserInfo("isurCd"))).indexOf('$' + '{') >= 0 ? '' : String(($c.session.getUserInfo("isurCd")) == null ? '' : ($c.session.getUserInfo("isurCd")))) === $c.util.getComponent("dma_RegisterReq").get("subcomIsurCd")){
        await $c.win.alert("상장자회사는 신청법인과 동일할 수 없습니다.");
        return false;
    }

    if("Y" === _submitYn){
        if( $c.util.getComponent("dma_RegisterReq").get("lnkDisclsApplSeq") === "" ){
            await $c.win.alert("제출하고자하는 임시저장 건을 목록에서 선택해주시기 바랍니다.");
            return false;
        }
    }

    if(!await scwin.chk())
    return;

    $c.util.getComponent("dma_RegisterReq").set("submitYn", _submitYn);

    if("Y" === _submitYn){
        await scwin.loadPop();
    }else{  // 임시저장
        $c.util.getComponent("dma_RegisterReq").set("method", 'registerLinkDisclsAppl');
        frm.action='linkDisclsAppl.do';
        await scwin.tx_fn_Register();
    }

};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @param {*} type type
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function (type) {
    if ("reg" !== type) {
        await $c.win.alert("잘못된 요청입니다. 다시 시도해주십시요");
        return false;
    }
    $c.util.getComponent("dma_RegisterReq").set("method", 'registerLinkDisclsAppl');
    await scwin.tx_fn_Submit('linkDisclsAppl.do');
};

/**
 * @method
 * @name findCompany
 * @description find Company 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findCompany = async function () {
    const corpSearchURL = '/ui/jsp/JLDFIL00033.xml';
    scwin.setCorpInfo_recv(await $c.win.openPopup(corpSearchURL, { id: "corpWin", scrollbars: false, resizable: false, width: "600", height: "570", type: "pageFramePopup" }, { method: "loadInitPage", marketType: "forLink" }));
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    $c.util.getComponent("dma_RegisterReq").set("subcomIsurCd", isurCd);
    $c.util.getComponent("ipt_subcomNm").setValue(comAbbrv);
};

/**
 * @method
 * @name goStatList
 * @description go Stat List 처리
 * @returns {void}
 * @hidden N
 */
scwin.goStatList = function () {
    const linkDisclsAppURL = '/ui/jsp/JLDFIL21100.xml';
    $c.win.setPageFrameSrc($c.win.getFrame(), linkDisclsAppURL);
};

/**
 * @method
 * @name loadPop
 * @description load Pop 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.loadPop = async function () {
    const linkDisclsAppURL = '/ui/jsp/JLDFIL21104.xml?type=reg';
    await $c.win.openPopup(linkDisclsAppURL, { id: "LinkDisclsNotice", scrollbars: false, resizable: false, width: "510", height: "730", type: "pageFramePopup" }, { method: "searchLinkDisclsApplList" });
};

/**
 * @method
 * @name setCorpInfo_recv
 * @description 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
 * @param {*} r r
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };
